<script setup lang="ts">import{ANCHOR_HORIZONS,MAX_YEAR,MIN_YEAR}from'../../core/models';defineProps<{timeline:number[]}>();const emit=defineEmits<{toggle:[year:number]}>();const years=Array.from({length:MAX_YEAR-MIN_YEAR+1},(_,i)=>MIN_YEAR+i);const isAnchor=(y:number)=>(ANCHOR_HORIZONS as readonly number[]).includes(y);</script>
<template><section class="paper-panel timeline-panel"><span class="index">03 / TIMELINE</span><h2>想在哪几年回头看？</h2><p>1 / 5 / 10 年是固定锚点，决定总分。点选其余年份加入观察，曲线会按锚点规则分段线性推算中间时点；不推测 10 年之外。</p><div class="year-chips"><button v-for="y in years" :key="y" type="button" :class="{anchor:isAnchor(y),on:!isAnchor(y)&&timeline.includes(y)}" :disabled="isAnchor(y)" :aria-pressed="!isAnchor(y)&&timeline.includes(y)" @click="emit('toggle',y)">{{y}}<small>{{isAnchor(y)?'锚点':timeline.includes(y)?'观察':'＋'}}</small></button></div></section></template>
